"""Build latency breakdowns for ``BotTurnEnded`` metadata.

The breakdown combines LLM and TTS timing from turn events with processor
execution times. Missing values are omitted when the model is serialized for
the Inspector.
"""

from typing import Any, Dict, List, Optional, Tuple

from pydantic import BaseModel, ConfigDict

from rasa.core.constants import (
    LLM_TIME_TO_FIRST_TOKEN_MS_KEY,
    LLM_TOTAL_TIME_MS_KEY,
)
from rasa.shared.core.events import BotUttered, Event, TTSFinished, UserUttered

# ---------------------------------------------------------------------------
# Models used by the Inspector
# ---------------------------------------------------------------------------


class AgentResponseLatency(BaseModel):
    """LLM timing for the first bot utterance of a turn."""

    model_config = ConfigDict(frozen=True)

    llm_time_to_first_token_ms: Optional[float] = None
    llm_total_generation_ms: Optional[float] = None
    generated_by_llm: bool


class VoiceResponseLatency(BaseModel):
    """TTS timing for the first voice completion of a turn."""

    model_config = ConfigDict(frozen=True)

    tts_time_to_first_byte_ms: Optional[float] = None
    tts_total_generation_ms: Optional[float] = None
    read_from_cache: Optional[bool] = None


class FullTurn(BaseModel):
    """Total server-side bot-turn time."""

    model_config = ConfigDict(frozen=True)

    prediction_loop_ms: float


class LatencyBreakdown(BaseModel):
    """Consolidated per-turn latency the Inspector reads from ``BotTurnEnded``.

    Serialize with ``model_dump(exclude_none=True)`` to omit unset fields.
    """

    model_config = ConfigDict(frozen=True)

    user_perceived_latency_ms: Optional[float] = None
    llm_generation_before_first_output_ms: Optional[float] = None
    command_generator_ms: Optional[float] = None
    full_turn: Optional[FullTurn] = None
    first_agent_response: Optional[AgentResponseLatency] = None
    first_voice_response: Optional[VoiceResponseLatency] = None


# ---------------------------------------------------------------------------
# Event readers
# ---------------------------------------------------------------------------


def first_agent_response_latency(
    turn_events: List[Event],
) -> Optional[AgentResponseLatency]:
    """Return LLM latency for the first bot utterance in the turn, or ``None``.

    Reads the ``llm_*`` keys from ``BotUttered.metadata``.
    ``generated_by_llm`` is ``False`` for deterministic/tool messages that carry
    no LLM timing.
    """
    first_bot_event = next(
        (event for event in turn_events if isinstance(event, BotUttered)), None
    )
    if first_bot_event is None:
        return None

    llm_time_to_first_token_ms = first_bot_event.metadata.get(
        LLM_TIME_TO_FIRST_TOKEN_MS_KEY
    )
    llm_total_generation_ms = first_bot_event.metadata.get(LLM_TOTAL_TIME_MS_KEY)
    return AgentResponseLatency(
        llm_time_to_first_token_ms=llm_time_to_first_token_ms,
        llm_total_generation_ms=llm_total_generation_ms,
        generated_by_llm=(
            llm_time_to_first_token_ms is not None
            or llm_total_generation_ms is not None
        ),
    )


def first_voice_response_latency(
    turn_events: List[Event],
) -> Optional[VoiceResponseLatency]:
    """Return TTS latency for the first voice completion in the turn, or ``None``.

    Reads the ``voice_latency`` block from ``TTSFinished.metadata``.
    """
    first_tts_event = next(
        (event for event in turn_events if isinstance(event, TTSFinished)), None
    )
    if first_tts_event is None:
        return None

    voice_latency = first_tts_event.metadata.get("voice_latency")
    if not isinstance(voice_latency, dict):
        return None

    read_from_cache = voice_latency.get("read_from_cache")
    if read_from_cache is None:
        read_from_cache = first_tts_event.metadata.get("read_from_cache")
    if not isinstance(read_from_cache, bool):
        read_from_cache = None

    tts_time_to_first_byte_ms = voice_latency.get("tts_time_to_first_byte_ms")
    tts_total_generation_ms = voice_latency.get("tts_total_time_ms")

    if (
        tts_time_to_first_byte_ms is None
        and tts_total_generation_ms is None
        and read_from_cache is None
    ):
        return None

    return VoiceResponseLatency(
        tts_time_to_first_byte_ms=tts_time_to_first_byte_ms,
        tts_total_generation_ms=tts_total_generation_ms,
        read_from_cache=read_from_cache,
    )


def llm_generation_before_first_output_ms(
    turn_events: List[Event], llm_calls: List[Dict[str, Any]]
) -> Optional[float]:
    """Sum recorded LLM calls completed before the first bot output.

    The call log is ephemeral, but it is the same source already rendered by
    the Inspector. Calls are scoped to the current user turn using event
    timestamps. When the first bot output contains LLM timing, the latest call
    before that output is the response-producing call and is excluded so its
    total duration is not double-counted with TTFT.
    """
    user_event = next(
        (event for event in turn_events if isinstance(event, UserUttered)), None
    )
    first_bot_event = next(
        (event for event in turn_events if isinstance(event, BotUttered)), None
    )
    if user_event is None or first_bot_event is None:
        return None

    current_turn_calls: List[Tuple[float, float]] = []
    for call in llm_calls:
        timestamp = call.get("timestamp")
        latency_ms = call.get("latency_ms")
        if not isinstance(timestamp, (int, float)) or not isinstance(
            latency_ms, (int, float)
        ):
            continue
        if user_event.timestamp <= timestamp <= first_bot_event.timestamp:
            current_turn_calls.append((float(timestamp), float(latency_ms)))
    current_turn_calls.sort()
    if not current_turn_calls:
        return None

    first_agent_response = first_agent_response_latency(turn_events)
    if first_agent_response is not None and first_agent_response.generated_by_llm:
        current_turn_calls = current_turn_calls[:-1]

    if not current_turn_calls:
        return None

    return sum(latency_ms for _, latency_ms in current_turn_calls)


# ---------------------------------------------------------------------------
# User-perceived latency
# ---------------------------------------------------------------------------


def calm_v1_user_perceived_latency_ms(
    first_agent_response: Optional[AgentResponseLatency],
    first_voice_response: Optional[VoiceResponseLatency],
    execution_times: Optional[Dict[str, float]],
) -> Optional[float]:
    """Return latency until the first response/audio can reach the user (CALM v1).

    The server-side floor is the ``command_processor`` phase, which precedes the
    LLM call, so the LLM's time-to-first-token is added on top, then the voice
    time-to-first-byte for voice turns.
    """
    if not execution_times:
        return None

    floor_ms = execution_times.get("command_processor")
    if not isinstance(floor_ms, (int, float)):
        return None

    latency_ms = float(floor_ms)
    has_response_latency = first_agent_response is not None

    if (
        first_agent_response is not None
        and first_agent_response.llm_time_to_first_token_ms is not None
    ):
        latency_ms += first_agent_response.llm_time_to_first_token_ms

    if (
        first_voice_response is not None
        and first_voice_response.tts_time_to_first_byte_ms is not None
    ):
        latency_ms += first_voice_response.tts_time_to_first_byte_ms
        has_response_latency = True

    return latency_ms if has_response_latency else None


# ---------------------------------------------------------------------------
# Breakdown builder
# ---------------------------------------------------------------------------


def build_calm_v1_latency_breakdown(
    turn_events: List[Event],
    execution_times: Optional[Dict[str, float]],
) -> LatencyBreakdown:
    """Assemble the CALM v1 breakdown for ``BotTurnEnded``.

    v1 populates a discrete ``command_generator_ms`` phase and the full-turn
    ``prediction_loop_ms`` on top of the shared first-response latencies.
    """
    first_agent_response = first_agent_response_latency(turn_events)
    first_voice_response = first_voice_response_latency(turn_events)

    execution_times = execution_times or {}
    prediction_loop_ms = execution_times.get("prediction_loop")
    return LatencyBreakdown(
        user_perceived_latency_ms=calm_v1_user_perceived_latency_ms(
            first_agent_response, first_voice_response, execution_times
        ),
        command_generator_ms=execution_times.get("command_processor"),
        full_turn=(
            FullTurn(prediction_loop_ms=prediction_loop_ms)
            if prediction_loop_ms is not None
            else None
        ),
        first_agent_response=first_agent_response,
        first_voice_response=first_voice_response,
    )


def build_mantle_latency_breakdown(
    turn_events: List[Event],
    user_perceived_latency_ms: float,
    llm_calls: Optional[List[Dict[str, Any]]] = None,
) -> LatencyBreakdown:
    """Assemble the engine's first-response latency breakdown."""
    return LatencyBreakdown(
        user_perceived_latency_ms=user_perceived_latency_ms,
        llm_generation_before_first_output_ms=llm_generation_before_first_output_ms(
            turn_events, llm_calls or []
        ),
        first_agent_response=first_agent_response_latency(turn_events),
        first_voice_response=first_voice_response_latency(turn_events),
    )
